/* ==UserStyle==
@name         DQHD Ultrawide Optimizer (5120×1440)
@namespace    dqhd-optimizer
@version      1.0.0
@description  Optimiert Webseiten für DQHD (5120×1440) Super-Ultrawide-Monitore. Erweitert Layouts, maximiert Platznutzung und verbessert die Lesbarkeit auf 32:9-Displays.
@author       Claude / Anthropic
@license      MIT
@preprocessor default
==/UserStyle== */

/* ============================================================
   DQHD ULTRAWIDE OPTIMIZER — 5120×1440 (32:9)
   Kompatibel mit: Stylish, Stylus
   
   ABSCHNITTE:
   1. Globale Layout-Korrekturen
   2. Maximale Breite erweitern
   3. Mehrspalten-Layout
   4. Navigation & Header
   5. Lesbarkeit & Typografie
   6. Seitenleisten & Panels
   7. Spezifische populäre Webseiten
   8. Mediaplayer & Videos
   9. Utility-Klassen & Overrides
   ============================================================ */

/* ============================================================
   1. GLOBALE LAYOUT-KORREKTUREN
   ============================================================ */

@media screen and (min-width: 3440px) {

  /* Verhindert übermäßiges Strecken von Textelementen */
  body {
    font-size: 18px !important;
  }

  /* Scrollbar immer sichtbar — verhindert Layout-Shifts */
  html {
    overflow-y: scroll;
  }

  /* ============================================================
     2. MAXIMALE BREITE ERWEITERN
     ============================================================ */

  /* Gängige Container-Klassen auf volle DQHD-Breite erweitern */
  .container,
  .container-fluid,
  .container-xl,
  .container-xxl,
  .container-lg,
  .container-md,
  .wrapper,
  .page-wrapper,
  .site-wrapper,
  .content-wrapper,
  .main-wrapper,
  .inner-wrapper,
  .layout-wrapper,
  .app-wrapper,
  [class*="container"],
  [class*="wrapper"],
  [class*="layout"] {
    max-width: 4800px !important;
    width: 95% !important;
    margin-left: auto !important;
    margin-right: auto !important;
  }

  /* Bootstrap- und Tailwind-spezifische Container */
  .max-w-screen-xl,
  .max-w-screen-2xl,
  .max-w-7xl,
  .max-w-6xl,
  .max-w-5xl {
    max-width: 4800px !important;
  }

  /* Häufig genutzte enge Breiten aufbrechen */
  [style*="max-width: 1"],
  [style*="max-width:1"] {
    max-width: 90vw !important;
  }

  /* ============================================================
     3. MEHRSPALTEN-LAYOUT
     ============================================================ */

  /* Lange Artikel und Feed-Listen in mehrere Spalten aufteilen */
  .feed,
  .news-feed,
  .article-list,
  .post-list,
  .card-grid,
  [class*="feed"],
  [class*="grid"],
  [class*="cards"] {
    display: grid !important;
    grid-template-columns: repeat(auto-fill, minmax(480px, 1fr)) !important;
    gap: 1.5rem !important;
  }

  /* Kommentar-Bereiche in zwei Spalten */
  .comments-list,
  .comment-list,
  [class*="comments"] {
    column-count: 2 !important;
    column-gap: 2rem !important;
    column-fill: balance !important;
  }

  /* ============================================================
     4. NAVIGATION & HEADER
     ============================================================ */

  /* Header und Navbars auf volle Breite strecken */
  header,
  .header,
  nav,
  .navbar,
  .nav-bar,
  .site-header,
  .page-header,
  .top-bar,
  .topbar,
  [class*="header"],
  [class*="navbar"],
  [class*="nav-bar"] {
    max-width: 100% !important;
    width: 100% !important;
  }

  /* Nav-Inhalte zentrieren aber Breite erhalten */
  .navbar-inner,
  .header-inner,
  .nav-inner,
  [class*="nav-inner"],
  [class*="header-inner"] {
    max-width: 4800px !important;
    margin: 0 auto !important;
    padding-left: 2rem !important;
    padding-right: 2rem !important;
  }

  /* Sticky-Header vertikal komprimieren */
  header[class*="sticky"],
  header[class*="fixed"],
  .sticky-header,
  .fixed-header {
    padding-top: 0.5rem !important;
    padding-bottom: 0.5rem !important;
  }

  /* ============================================================
     5. LESBARKEIT & TYPOGRAFIE
     ============================================================ */

  /* Artikel-Texte: optimale Zeilenlänge auch auf DQHD */
  article,
  .article,
  .article-body,
  .post-body,
  .entry-content,
  .content-body,
  .story-body,
  [class*="article-content"],
  [class*="post-content"],
  [class*="entry-content"] {
    max-width: 900px !important;
    margin-left: auto !important;
    margin-right: auto !important;
    font-size: 1.1rem !important;
    line-height: 1.8 !important;
  }

  /* Überschriften skalieren */
  h1 { font-size: clamp(2rem, 2.5vw, 4rem) !important; }
  h2 { font-size: clamp(1.5rem, 2vw,  3rem) !important; }
  h3 { font-size: clamp(1.2rem, 1.5vw, 2.2rem) !important; }

  /* ============================================================
     6. SEITENLEISTEN & PANELS
     ============================================================ */

  /* Seitenleisten sichtbar machen und verbreitern */
  aside,
  .sidebar,
  .side-panel,
  .side-bar,
  [class*="sidebar"],
  [class*="side-panel"] {
    display: block !important;
    min-width: 320px !important;
    max-width: 420px !important;
    flex-shrink: 0 !important;
  }

  /* Hauptinhalt + Sidebar nebeneinander */
  .layout-with-sidebar,
  .main-with-sidebar,
  .content-with-sidebar,
  [class*="with-sidebar"] {
    display: flex !important;
    gap: 2rem !important;
    align-items: flex-start !important;
  }

  /* ============================================================
     7. SPEZIFISCHE POPULÄRE WEBSEITEN
     ============================================================ */

  /* — — — GitHub — — — */
  .application-main .container-xl,
  .application-main .container-lg {
    max-width: 4800px !important;
  }

  .repository-content,
  .Layout-main {
    max-width: 100% !important;
  }

  /* Diff-Ansicht nutzt volle Breite */
  .diff-table,
  .file-diff {
    width: 100% !important;
    max-width: 100% !important;
  }

  /* — — — Reddit — — — */
  .ListingLayout-outerContainer,
  ._1Qfoi-7XBNiTEsBO2E6Lxl,
  [class*="ListingLayout"] {
    max-width: 4800px !important;
  }

  /* Old Reddit */
  #content-container,
  .content > .spacer {
    max-width: 4800px !important;
    width: 95vw !important;
  }

  /* — — — YouTube — — — */
  ytd-page-manager,
  #page-manager {
    margin: 0 auto !important;
    max-width: 4800px !important;
  }

  ytd-browse[page-subtype="home"] #primary ytd-rich-grid-renderer {
    --ytd-rich-grid-items-per-row: 8 !important;
  }

  #player-theater-container,
  ytd-watch-flexy[theater] #player-theater-container {
    max-height: 75vh !important;
  }

  /* — — — Twitter / X — — — */
  main[role="main"],
  .css-175oi2r[style*="width: 600px"],
  [data-testid="primaryColumn"] {
    max-width: 800px !important;
  }

  /* Trending & Explore-Spalte erhalten */
  [data-testid="sidebarColumn"] {
    display: block !important;
    width: 380px !important;
  }

  /* — — — Wikipedia — — — */
  #content,
  .mw-page-container,
  .mw-content-container {
    max-width: 4000px !important;
    padding: 0 3rem !important;
  }

  .mw-parser-output {
    font-size: 1rem !important;
    line-height: 1.75 !important;
    column-count: 2 !important;
    column-gap: 4rem !important;
    column-fill: balance !important;
  }

  /* Infoboxen aus Spalten rausnehmen */
  .infobox,
  .wikitable,
  .navbox,
  .thumb {
    column-span: none !important;
    break-inside: avoid !important;
  }

  /* — — — Stack Overflow — — — */
  #content,
  .container.mx-auto,
  .s-container {
    max-width: 4800px !important;
    width: 95% !important;
  }

  #mainbar {
    width: auto !important;
    flex: 1 !important;
  }

  /* — — — Hacker News — — — */
  table#hnmain {
    width: 90% !important;
    max-width: 4000px !important;
    margin: 0 auto !important;
  }

  /* — — — MDN Web Docs — — — */
  .page-wrapper,
  .main-page-content {
    max-width: 4800px !important;
  }

  /* — — — Discord (Web) — — — */
  [class*="app-"] {
    max-width: 100% !important;
  }

  /* — — — Twitch — — — */
  .channel-root,
  .root-scrollable {
    max-width: 100% !important;
  }

  /* — — — Amazon — — — */
  #a-page,
  .a-section.a-spacing-base {
    max-width: 4800px !important;
    width: 95% !important;
  }

  /* Produktgalerie: mehr Einträge pro Zeile */
  [class*="s-main-slot"] .s-result-item {
    width: calc(20% - 1rem) !important;
    max-width: 300px !important;
  }

  /* — — — Google Suche — — — */
  #rcnt,
  #center_col,
  #rso {
    max-width: 4000px !important;
    width: 70vw !important;
  }

  /* Suchergebnisse zweispaltig */
  #rso {
    column-count: 2 !important;
    column-gap: 3rem !important;
  }

  #rso > div {
    break-inside: avoid !important;
  }

  /* — — — Notion — — — */
  .notion-page-content,
  .notion-scroller {
    max-width: 4000px !important;
    padding: 0 4rem !important;
  }

  /* — — — ChatGPT / OpenAI — — — */
  .flex.flex-col.items-center,
  [class*="prose"] {
    max-width: 900px !important;
  }

  /* — — — Linear — — — */
  [class*="WorkspaceIssues"],
  [class*="IssueList"] {
    max-width: 100% !important;
  }

  /* ============================================================
     8. MEDIAPLAYER & VIDEOS
     ============================================================ */

  /* Videos nicht übermäßig strecken */
  video,
  iframe[src*="youtube"],
  iframe[src*="vimeo"],
  .video-player,
  [class*="video-container"] {
    max-height: 80vh !important;
    width: auto !important;
    margin: 0 auto !important;
  }

  /* Vollbreite Video-Player */
  .video-js,
  .plyr,
  [class*="player--full"] {
    max-width: 100% !important;
    max-height: 85vh !important;
  }

  /* ============================================================
     9. UTILITY-OVERRIDES & FINE-TUNING
     ============================================================ */

  /* Modals zentriert halten */
  .modal,
  .modal-dialog,
  .dialog,
  [role="dialog"],
  [class*="modal"] {
    max-width: min(900px, 90vw) !important;
    left: 50% !important;
    transform: translateX(-50%) !important;
  }

  /* Tooltips & Dropdowns nicht strecken */
  .tooltip,
  .dropdown-menu,
  .popover,
  [class*="tooltip"],
  [class*="dropdown"] {
    max-width: 400px !important;
    width: auto !important;
  }

  /* Code-Blöcke: horizontal scrollbar statt umbrechen */
  pre,
  code,
  .highlight,
  [class*="code-block"] {
    max-width: 100% !important;
    overflow-x: auto !important;
    white-space: pre !important;
  }

  /* Tabellen: scrollbar bei Überlauf */
  table {
    display: block !important;
    overflow-x: auto !important;
    max-width: 100% !important;
  }

  /* Bilder skalieren aber nicht überdehnen */
  img {
    max-width: 100% !important;
    height: auto !important;
  }

  /* Formulare: nicht auf volle Breite strecken */
  form,
  .form,
  [class*="form-container"] {
    max-width: 700px !important;
  }

  /* Input-Felder angemessen breit */
  input[type="text"],
  input[type="email"],
  input[type="search"],
  input[type="url"],
  textarea {
    max-width: 100% !important;
    min-width: 300px !important;
  }

  /* Fokus-Indikatoren für große Displays besser sichtbar */
  :focus-visible {
    outline-width: 3px !important;
    outline-offset: 3px !important;
  }

} /* Ende @media screen and (min-width: 3440px) */


/* ============================================================
   DQHD-SPEZIFISCH: Nur ab 5120px Breite
   ============================================================ */
@media screen and (min-width: 5000px) {

  body {
    font-size: 20px !important;
  }

  /* Noch mehr Spalten auf echter DQHD-Breite */
  ytd-browse[page-subtype="home"] #primary ytd-rich-grid-renderer {
    --ytd-rich-grid-items-per-row: 10 !important;
  }

  #rso {
    column-count: 3 !important;
  }

  .mw-parser-output {
    column-count: 3 !important;
  }

  h1 { font-size: clamp(2.5rem, 2vw, 5rem) !important; }
  h2 { font-size: clamp(2rem, 1.5vw, 4rem) !important; }

}
